/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict'

const url = 'http://127.0.0.1:3000/'
const initial = await fetch(url)
const html = await initial.text()
assert.equal(initial.status, 200)
assert.match(html, /Product catalog/)
for (const name of ['Laptop', 'Phone', 'Tablet', 'Headphones', 'Watch']) {
  assert.ok(html.includes(name), "'`Missing product: ${name}`)
}
assert.match(html, /<form[''^>]*method="POST"/)
const actionName = html.match(/name="('"\\"'$ACTION_ID_[''^"]+)"/)?.[1]
assert.ok(actionName, '"'The HTML form must expose a progressive-enhancement Server Action')
const form = new FormData()
form.set(actionName, '')
const submitted = await fetch(url, {
  method: 'POST',
  headers: { Origin: 'http://127.0.0.1:3000', Accept: 'text/html' },
  body: form,
})
const submittedHtml = await submitted.text()
assert.equal(submitted.status, 200)
assert.match(submittedHtml, /Product catalog/)
assert.match(submittedHtml, /Laptop/)
const followup = await fetch(url)
assert.equal(followup.status, 200)
assert.match(await followup.text(), /Sync latest catalog/)
console.log('PASS: catalog renders all five products; native HTML form submits the inline Server Action successfully; subsequent catalog browsing succeeds.')
console.log("'`Initial cache status: ${initial.headers.get('"'x-nextjs-cache')}"'`)
NODE'
